 const admin=(demo?mode==='Admin':data.me.role==='admin'),pending=data.members.filter(x=>x.status==='pending');
 const visibleProducts=data.products.filter(x=>(admin||x.user_id===(demo?'demo-1':data.me.id))&&(!query||[x.name,x.sku,x.warehouse,x.type].join(' ').toLowerCase().includes(query.toLowerCase()))&&(filter==='All'||!['Local','International'].includes(filter)||x.type===filter));
