 async function reload(){const current=getFirebaseAuth().currentUser;if(!current){setAuth(false);return;}const token=await current.getIdToken();const r=await fetch('/api/workspace',{headers:{Authorization:'Bearer '+token}});const d:any=await r.json();if(!r.ok){setSetupRequired(!!d.setupRequired);throw new Error(d.error||'Unable to load workspace.');}if(getFirebaseAuth().currentUser?.uid!==current.uid)return;setData(d);setLoadedUid(current.uid);setDemo(false);setAuth(true);setSetupRequired(false);setError('');}
