 useEffect(()=>{if(!modal)return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector('[role="dialog"]') as HTMLElement|null;const focusables=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled])')||[]);focusables()[0]?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)setModal(null);if(e.key==='Tab'){const f=focusables(),first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus();};},[modal,busy]);
 function go(s:string){setTab(s);setFilter('All');setQuery('');setMenu(false);}
 function demoMutate(b:any){setData(prev=>{let d=structuredClone(prev);const now=new Date().toISOString();const id='DEMO-'+Math.random().toString(36).slice(2,8).toUpperCase();if(b.action==='approve'||b.action==='reject')d.members=d.members.map(x=>x.id===b.id?{...x,status:b.action==='approve'?'approved':'rejected'}:x);if(b.action==='rate'){d.rate=Number(b.rate);d.rateConfigured=true;}if(b.action==='profile'){d.members=d.members.map(x=>x.id===(b.id||d.me.id)?{...x,name:b.name,company:b.company,phone:b.phone}:x);if(!b.id||b.id===d.me.id)d.me={...d.me,name:b.name,company:b.company,phone:b.phone};}if(b.action==='product'){let p={...b,id:b.id||id,price:Math.round(Number(b.price)*100),available:Number(b.available),created:now};d.products=b.id?d.products.map(x=>x.id===b.id?p:x):[p,...d.products];}if(b.action==='ship'){let p=d.products.find(x=>x.id===b.product_id)!;const u=Number(b.units);d.shipments.unshift({...b,id,user_id:p.user_id,product_name:p.name,price:p.price,rate:d.rate,units:u,status:'Waiting for approval',tracking:'',reserved:false,created:now,updated:now});d.events.unshift({id,shipment_id:id,status:'Waiting for approval',message:'FBA shipment request submitted. Waiting for administrator approval.',location:p.warehouse,created:now});}if(b.action==='shipment'){const old=d.shipments.find(s=>s.id===b.id)!;if(b.status==='Order booked'&&old.status==='Waiting for approval')d.products=d.products.map(p=>p.id===old.product_id?{...p,available:p.available-old.units}:p);if(b.status==='Cancelled'&&old.status!=='Cancelled'&&old.status!=='Waiting for approval')d.products=d.products.map(p=>p.id===old.product_id?{...p,available:p.available+old.units}:p);d.shipments=d.shipments.map(x=>x.id===b.id?{...x,status:b.status,tracking:b.tracking,updated:now}:x);d.events.unshift({id,shipment_id:b.id,status:b.status,message:b.message||b.status,location:b.location,created:now});}d.activity.unshift({id,user_id:b.user_id||d.me.id,message:b.action==='ship'?'FBA shipment request submitted':b.action==='shipment'?`Shipment updated: ${b.status}`:b.action==='product'?`Product assigned: ${b.name}`:'Workspace updated',created:now});return d;});}
 async function act(b:any){setBusy(true);try{if(demo){if(b.action==='shipment'&&b.status==='Order booked'){const s=data.shipments.find(s=>s.id===b.id);if(s?.status==='Waiting for approval'&&(data.products.find(p=>p.id===s.product_id)?.available||0)<s.units)throw new Error('Not enough stock remains to approve this request.');}demoMutate(b);notify('Demo updated. Sign in to save your real workspace.');}else{const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await getFirebaseAuth().currentUser!.getIdToken()},body:JSON.stringify(b)});const result:any=await r.json();if(!r.ok)throw new Error(result.error);await reload();notify(b.action==='ship'?'Request submitted. Waiting for approval.':'Changes saved successfully.');}setModal(null);}catch(e:any){notify(e.message);}finally{setBusy(false);}}
 function submit(e:React.FormEvent<HTMLFormElement>,action:string,extra:any={}){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));act({...f,...extra,action});}
 function exportCSV(){const rows=[['Product','SKU','Type','Warehouse','Unit USD','Unit PKR','Available','Total USD','Total PKR'],...visibleProducts.map(p=>[p.name,p.sku,p.type,p.warehouse,(p.price/100).toFixed(2),(p.price/100*data.rate).toFixed(2),p.available,(p.price*p.available/100).toFixed(2),(p.price*p.available/100*data.rate).toFixed(2)])];const blob=new Blob([rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='auronix-inventory.csv';a.click();URL.revokeObjectURL(a.href);notify('Inventory exported.');}
