 const productTable=(limit?:number)=><div className="table-scroll"><table><thead><tr><th>PRODUCT DETAILS</th>{admin&&<th>ASSIGNED TO</th>}<th>UNIT PRICE</th><th>AVAILABLE</th><th>INVENTORY VALUE</th><th/></tr></thead><tbody>{visibleProducts.slice(0,limit).map(p=><tr key={p.id}><td><button className="table-product" onClick={()=>setModal({kind:'detail',item:p})}><span className="thumb"><ProductImage src={p.image} name={p.name}/></span><span><b>{p.name}</b><small>{p.sku} <span className="dot-separator">·</span> {p.type}</small><small><MapPin size={12}/>{p.warehouse}</small></span></button></td>{admin&&<td><button className="user-link" onClick={()=>setModal({kind:'user',item:data.members.find(x=>x.id===p.user_id)})}><span className="mini-avatar">{person(p.user_id).slice(0,1)}</span>{person(p.user_id)}</button></td>}<td><b>{usd(p.price)}</b><small>{pkr(p.price,data.rate)}</small></td><td><b className="stock">{p.available.toLocaleString()} <span>units</span></b><small className={p.available>25?'positive':'warning'}>{p.available===0?'Out of stock':p.available<=25?'Low stock':'In stock'}</small></td><td><b>{usd(p.price*p.available)}</b><small>{pkr(p.price*p.available,data.rate)}</small></td><td><button className="icon-button" aria-label={'View '+p.name} onClick={()=>setModal({kind:'detail',item:p})}><MoreHorizontal size={20}/></button></td></tr>)}</tbody></table>{!visibleProducts.length&&noData('Your next opportunity starts here',admin?'Open an approved user profile to assign your first product.':'Your assigned products will appear here once your sourcing team adds them.')}</div>;
