 {tab==='Products'&&<section><div className="toolbar"><div className="filter-tabs">{['All','International','Local'].map(x=><button key={x} className={filter===x?'selected':''} onClick={()=>setFilter(x)}>{x==='All'?'All products':x}{x==='All'&&<span>{data.products.filter(p=>admin||p.user_id===(demo?'demo-1':data.me.id)).length}</span>}</button>)}</div><div className="search"><Search size={17}/><input placeholder="Search products, SKU, warehouse…" value={query} onChange={e=>setQuery(e.target.value)} aria-label="Search products"/></div></div><div className="product-grid">{visibleProducts.map(p=><article className="product-card" key={p.id}><div className="product-photo"><ProductImage src={p.image} name={p.name}/><Badge>{p.type}</Badge>{admin&&<button className="icon-button" aria-label={'Edit '+p.name} onClick={()=>setModal({kind:'product',item:p})}><MoreHorizontal size={20}/></button>}</div><div className="product-content"><span className="product-category">{p.category} <span>· {p.sku}</span></span><h3><button onClick={()=>setModal({kind:'detail',item:p})}>{p.name}</button></h3><div className="warehouse"><MapPin size={14}/>{p.warehouse}</div>{admin&&<div className="assigned-label">Assigned to <button onClick={()=>setModal({kind:'user',item:data.members.find(m=>m.id===p.user_id)})}>{person(p.user_id)}</button></div>}<div className="product-pricing"><div><small>Single unit</small><strong>{usd(p.price)}</strong><span>{pkr(p.price,data.rate)}</span></div><div className="align-right"><small>Available stock</small><strong>{p.available.toLocaleString()} <em>units</em></strong><span className={p.available>25?'positive':'warning'}>{p.available>25?'In stock':p.available>0?'Low stock':'Out of stock'}</span></div></div><div className="quantity-row"><label>Quantity{selectQty(p)}</label><div><small>Selected total</small><b>{usd(p.price*qty(p))}</b><span>{pkr(p.price*qty(p),data.rate)}</span></div></div><button className="primary full-width" disabled={p.available<1} onClick={()=>openShip(p)}><Truck size={17}/>Ship to FBA address</button></div></article>)}</div>{!visibleProducts.length&&noData('No products found',query?'Try a different name, SKU, or warehouse.':'Assigned products will appear here.') }<p className="currency-note">USD prices are the source of truth. PKR uses the {data.rateConfigured?'admin-set':'illustrative'} rate of 1 USD = {data.rate} PKR. Product totals exclude shipping, duties, and Amazon fees.</p></section>}
